using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalFoliageWindFinish {
const string Dir="Assets/Scenes/Oasis/CoastalTerrain";
static CoastalFoliageWindFinish(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalFoliageWindFinish.request"))return;try{File.Delete("CoastalFoliageWindFinish.request");}catch(IOException){return;}Run();}
static int plants,vertices,pinned;static HashSet<Mesh> seen=new HashSet<Mesh>();
static void Improve(Mesh mesh,int stride){if(!mesh||!seen.Add(mesh))return;var existing=new List<Vector4>();mesh.GetUVs(1,existing);if(existing.Count==mesh.vertexCount&&existing.Any(v=>v.x>0))return;
var p=mesh.vertices;var uv=mesh.uv;var normals=mesh.normals;var active=new HashSet<int>(mesh.triangles);var np=new List<Vector3>();var nu=new List<Vector2>();var nn=new List<Vector3>();var nw=new List<Vector4>();var ids=new List<int>();int segments=stride==12?4:2;
for(int start=0;start<p.Length;start+=stride){int end=Math.Min(start+stride,p.Length);float min=100000,max=-100000;Vector3 center=Vector3.zero;for(int j=start;j<end;j++){min=Mathf.Min(min,p[j].y);max=Mathf.Max(max,p[j].y);center+=p[j];}center/=(end-start);bool used=false;
for(int q=start;q+3<end;q+=4){if(!Enumerable.Range(q,4).All(active.Contains))continue;used=true;int first=np.Count;for(int row=0;row<=segments;row++){float t=row/(float)segments;for(int side=0;side<2;side++){var v=Vector3.Lerp(p[q+side],p[q+2+side],t);np.Add(v);nu.Add(Vector2.Lerp(uv[q+side],uv[q+2+side],t));nn.Add(normals.Length==p.Length?normals[q+side]:Vector3.up);float w=Mathf.InverseLerp(min,max,v.y);nw.Add(new Vector4(w,center.x,center.z,0));if(w<.00001f)pinned++;}}for(int row=0;row<segments;row++){int a=first+row*2;ids.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}
if(used)plants++;}
mesh.Clear();mesh.indexFormat=np.Count>65535?UnityEngine.Rendering.IndexFormat.UInt32:UnityEngine.Rendering.IndexFormat.UInt16;mesh.SetVertices(np);mesh.SetUVs(0,nu);mesh.SetUVs(1,nw);mesh.SetNormals(nn);mesh.SetTriangles(ids,0);mesh.RecalculateBounds();var b=mesh.bounds;b.Expand(.6f);mesh.bounds=b;vertices+=np.Count;EditorUtility.SetDirty(mesh);}
static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){string name=f.transform.parent?f.transform.parent.name:"";if(name.StartsWith("Pine_")||name.StartsWith("Shrub_"))Improve(f.sharedMesh,f.name=="Detailed"?12:8);}
for(int i=0;i<3;i++)foreach(string kind in new[]{"Pine","Shrub"}){Improve(AssetDatabase.LoadAssetAtPath<Mesh>(Dir+"/Details/"+kind+" "+i+".asset"),12);Improve(AssetDatabase.LoadAssetAtPath<Mesh>(Dir+"/Details/"+kind+" "+i+" distant.asset"),8);}
var importer=(TextureImporter)AssetImporter.GetAtPath(Dir+"/Details/Natural Pine and Woodland Shrubs.png");importer.npotScale=TextureImporterNPOTScale.None;importer.anisoLevel=4;importer.filterMode=FilterMode.Trilinear;importer.mipmapEnabled=true;importer.mipMapsPreserveCoverage=true;importer.streamingMipmaps=true;foreach(var platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_4x4,compressionQuality=90});importer.SaveAndReimport();
var materials=new[]{AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Details/Shared mountain pine.mat"),AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Details/Shared mountain shrub.mat")};for(int i=0;i<2;i++){var m=materials[i];m.SetFloat("_WindStrength",i==0?.18f:.065f);m.SetFloat("_WindSpeed",i==0?.95f:1.25f);m.SetFloat("_PreviewTime",-1);m.enableInstancing=true;EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();
foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{Dir+"/Prefabs"})){string path=AssetDatabase.GUIDToAssetPath(guid);if(!path.Contains("Pine")&&!path.Contains("Shrub"))continue;var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var lod in prefab.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}
foreach(var lod in root.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);foreach(var m in materials)m.SetFloat("_PreviewTime",0);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Improved-Foliage-Wind-A"});foreach(var m in materials)m.SetFloat("_PreviewTime",2);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Improved-Foliage-Wind-B"});foreach(var m in materials){m.SetFloat("_PreviewTime",-1);EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();var shader=materials[0].shader;int errors=ShaderUtil.GetShaderMessages(shader).Count(m=>m.severity.ToString()=="Error");File.WriteAllText("FinalEnvironmentRoadReview/CoastalFoliageWindReport.txt","SUCCESS meshes="+seen.Count+" plant LOD representations="+plants+" vertices="+vertices+" pinned base vertices="+pinned+" shader errors="+errors+"; shared GPU wind across forward/depth/normals/shadows; live preview restored; ASTC4x4 foliage; existing prefab layout retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoastalFoliageWindReport.txt","FAILED "+e);Debug.LogException(e);}}
}
